expand_details.cypher:
MATCH (start:namespace {name: 'default'})
CALL apoc.path.expandConfig(start, {
    sequence: 'namespace,encapsulates,deployment,controls,replicaset,manages,pod,restart_count',
    minLevel: 0,
    maxLevel: 3,
    bfs: true
})
YIELD path
RETURN path, length(path) AS hops
ORDER BY hops;

